import base64
import hashlib
import secrets
import time
from dataclasses import dataclass
from typing import Any, Dict, Optional
from urllib.parse import urlencode, urljoin

import requests


@dataclass
class PKCELoginConfig:
    auth0_domain: str
    client_id: str
    redirect_uri: str
    audience: Optional[str] = None
    scope: str = "openid profile email offline_access"
    timeout_seconds: int = 15

    @property
    def issuer(self) -> str:
        return f"https://{self.auth0_domain}/"

    @property
    def authorize_endpoint(self) -> str:
        return f"https://{self.auth0_domain}/authorize"

    @property
    def token_endpoint(self) -> str:
        return f"https://{self.auth0_domain}/oauth/token"

    @property
    def userinfo_endpoint(self) -> str:
        return f"https://{self.auth0_domain}/userinfo"


@dataclass
class PKCELoginSession:
    state: str
    code_verifier: str
    code_challenge: str
    code_challenge_method: str = "S256"
    created_at: float = 0.0


class Auth0PKCEClient:
    def __init__(self, config: PKCELoginConfig):
        self.config = config
        self.session = requests.Session()

    @staticmethod
    def _b64url_no_pad(data: bytes) -> str:
        return base64.urlsafe_b64encode(data).decode("ascii").rstrip("=")

    def create_pkce_session(self) -> PKCELoginSession:
        code_verifier = self._b64url_no_pad(secrets.token_bytes(32))
        code_challenge = self._b64url_no_pad(hashlib.sha256(code_verifier.encode("ascii")).digest())
        state = self._b64url_no_pad(secrets.token_bytes(24))
        return PKCELoginSession(
            state=state,
            code_verifier=code_verifier,
            code_challenge=code_challenge,
            created_at=time.time(),
        )

    def build_authorization_url(self, pkce_session: PKCELoginSession, extra_params: Optional[Dict[str, str]] = None) -> str:
        params = {
            "response_type": "code",
            "client_id": self.config.client_id,
            "redirect_uri": self.config.redirect_uri,
            "scope": self.config.scope,
            "state": pkce_session.state,
            "code_challenge": pkce_session.code_challenge,
            "code_challenge_method": pkce_session.code_challenge_method,
        }
        if self.config.audience:
            params["audience"] = self.config.audience
        if extra_params:
            params.update(extra_params)
        return f"{self.config.authorize_endpoint}?{urlencode(params)}"

    def exchange_code_for_tokens(self, authorization_code: str, pkce_session: PKCELoginSession) -> Dict[str, Any]:
        payload = {
            "grant_type": "authorization_code",
            "client_id": self.config.client_id,
            "code": authorization_code,
            "redirect_uri": self.config.redirect_uri,
            "code_verifier": pkce_session.code_verifier,
        }
        response = self.session.post(
            self.config.token_endpoint,
            json=payload,
            timeout=self.config.timeout_seconds,
            headers={"Content-Type": "application/json"},
        )
        response.raise_for_status()
        return response.json()

    def fetch_userinfo(self, access_token: str) -> Dict[str, Any]:
        response = self.session.get(
            self.config.userinfo_endpoint,
            headers={"Authorization": f"Bearer {access_token}"},
            timeout=self.config.timeout_seconds,
        )
        response.raise_for_status()
        return response.json()

    def login_flow(self, authorization_code: str, pkce_session: PKCELoginSession) -> Dict[str, Any]:
        token_response = self.exchange_code_for_tokens(authorization_code, pkce_session)
        access_token = token_response.get("access_token")
        id_token = token_response.get("id_token")
        userinfo = self.fetch_userinfo(access_token) if access_token else {}
        return {
            "tokens": token_response,
            "userinfo": userinfo,
            "id_token": id_token,
        }


def build_auth0_pkce_client() -> Auth0PKCEClient:
    import os

    domain = os.environ["AUTH0_DOMAIN"]
    client_id = os.environ["AUTH0_CLIENT_ID"]
    redirect_uri = os.environ["AUTH0_REDIRECT_URI"]
    audience = os.getenv("AUTH0_AUDIENCE")
    scope = os.getenv("AUTH0_SCOPE", "openid profile email offline_access")
    return Auth0PKCEClient(
        PKCELoginConfig(
            auth0_domain=domain,
            client_id=client_id,
            redirect_uri=redirect_uri,
            audience=audience,
            scope=scope,
        )
    )
